using System;namespace Recovered.Gameplay {public static class PtlRuntimeVersionFields {static uint Field(SoundSetupImage m,uint output,uint field,Func<SoundSetupImage,uint,uint[],uint> leaf){if(output==0||m.Word(0x297c1b4)==0){uint error=leaf(m,0x6ead5f,new uint[0]);m.Word(error,22);leaf(m,0x6e9fc2,new uint[]{0,0,0,0,0});return 22;}m.Word(output,m.Word(field));return 0;}public static uint Minor(SoundSetupImage m,uint output,Func<SoundSetupImage,uint,uint[],uint> leaf){return Field(m,output,0x297c1b8,leaf);}public static uint Build(SoundSetupImage m,uint output,Func<SoundSetupImage,uint,uint[],uint> leaf){return Field(m,output,0x297c1bc,leaf);}}}
